import math
from fractions import Fraction

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def calculate_ratio_Kn(n):
    f_n = combinations(n, 3)
    g_n = combinations(n, 4)

    if f_n == 0:
        return 0.0

    # R(n) = g(K_n)^3 / f(K_n)^4
    return (g_n**3) / (f_n**4)

# Test values:
print(f"R(7) = {calculate_ratio_Kn(7)}")
print(f"R(10) = {calculate_ratio_Kn(10)}")
print(f"R(15) = {calculate_ratio_Kn(15)}")
print(f"R(20) = {calculate_ratio_Kn(20)}")
